import argparse,json,math,pathlib,struct
P=pathlib.Path(__file__).parent
M,N,K=16,3840,15360

def bf(raw):
 return [struct.unpack('<f',struct.pack('<I',v<<16))[0] for (v,) in struct.iter_unpack('<H',raw)]
def metrics(a,b):
 assert len(a)==len(b) and len(a)>0
 assert all(math.isfinite(v) for v in a+b),'nonfinite'
 ss=sum((x-y)**2 for x,y in zip(a,b));den=sum(x*x for x in a)
 return dict(rel_l2=math.sqrt(ss/max(den,1e-30)),max_abs=max(abs(x-y) for x,y in zip(a,b)),max_ref=max(abs(x) for x in a))
def compare(a,b,limit):
 v=metrics(a,b);assert v['rel_l2']<=limit and v['max_abs']<=.05+.02*v['max_ref'],v;return v
def read(directory):
 manifest=json.loads((directory/'manifest.json').read_text())
 assert manifest['batch']==16 and manifest['input_batch']==16 and manifest['reset_at']==3
 assert manifest['token_ids']==[2,42,43,2,42,43] and len(manifest['steps'])==6
 rows=[]
 for step in manifest['steps']:
  row={d['name']:(directory/d['file']).read_bytes() for d in step['tensors']}
  for name,n in [('act.fu',M*K*2),('act.dg',M*N*2),('act.x',M*N*2)]:
   assert len(row[name])>=n;row[name]=row[name][:n]
   assert all(math.isfinite(v) for v in bf(row[name]))
  rows.append(row)
 return manifest,rows

def canary(row):
 raw=row['act.e3.partial.22'];assert len(raw)==M*N*4+256
 assert raw[M*N*4:]==b'\xa5\x5a'*128,'scratch guard changed'
 vals=struct.unpack('<'+'f'*(M*N),raw[:M*N*4]);assert all(math.isfinite(v) for v in vals),'poison survived zero/compute'
 words=struct.unpack('<'+'I'*(M*N),raw[:M*N*4]);rounded=b''.join(struct.pack('<H',((v+0x7fff+((v>>16)&1))>>16)&65535) for v in words)
 assert rounded==row['act.dg'],'cast is not exact BF16(final FP32 plane)'

def run():
 records=[]
 for seed in [0,1]:
  cm,c=read(P/'results'/f'e3-phaseA-control-seed{seed}');sm,s=read(P/'results'/f'e3-phaseA-s8-seed{seed}')
  assert sm['scratch_canary']==['act.e3.partial.22',M*N*4,256]
  for step,(control,candidate) in enumerate(zip(c,s)):
   assert control['act.fu']==candidate['act.fu'],'upstream projection input changed'
   canary(candidate)
   for name,limit in [('act.dg',.006),('act.x',.01)]:
    a=bf(control[name]);b=bf(candidate[name])
    for slot in range(M):
     v=compare(a[slot*N:(slot+1)*N],b[slot*N:(slot+1)*N],limit)
     records.append(dict(seed=seed,step=step,slot=slot,tensor=name,**v))
   if step>=3:
    for name in ['act.fu','act.dg','act.x']:assert control[name]==c[step-3][name],'control reset did not reproduce history'
    for name,limit in [('act.dg',.006),('act.x',.01)]:compare(bf(s[step-3][name]),bf(candidate[name]),limit)
 result=dict(numerical_pass=True,seeds=2,steps_per_arm=12,physical_rows_per_step=16,scratch_canary_checks=12,per_row_comparisons=records,scope='isolated M16 block only; sanitizer and full-model gates remain separate',device_memory_qualified=False)
 (P/'numerical-qualification.json').write_text(json.dumps(result,indent=2)+'\n');print('PASS numerical: 384 per-row comparisons, 12 scratch/cast guards, repeated history/reset; no sanitizer qualification implied')

def self_test():
 assert compare([1.,2.],[1.,2.],.006)['rel_l2']==0
 rejected=0
 for x,y in [([1.],[float('nan')]),([1.],[2.]),([0.],[.1])]:
  try:compare(x,y,.006)
  except AssertionError:rejected+=1
 assert rejected==3
 raw=struct.pack('<f',1.)*(M*N)+b'\xa5\x5a'*128
 row={'act.e3.partial.22':raw,'act.dg':struct.pack('<H',0x3f80)*(M*N)};canary(row)
 for key,idx in [('act.e3.partial.22',len(raw)-1),('act.dg',0),('act.e3.partial.22',3)]:
  bad=dict(row);v=bytearray(bad[key]);v[idx]^=0xff;bad[key]=bytes(v)
  try:canary(bad)
  except AssertionError:rejected+=1
 assert rejected==6
 print('PASS CPU-only synthetic parser: exact row and guard accepted; six error/canary/cast/poison mutations rejected')
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--self-test',action='store_true');args=ap.parse_args()
 if args.self_test:self_test()
 else:run()

